"""Fetcher regressions use generated bytes only; no study images or network."""
import contextlib
import hashlib
import importlib.util
import io
import json
import socket
import struct
import tempfile
import unittest
import zipfile
import zlib
from pathlib import Path
from unittest import mock


SPEC = importlib.util.spec_from_file_location(
    "fetch_rsna_control", Path(__file__).resolve().parents[1] / "scripts/fetch_rsna_control.py")
fetch = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(fetch)


class Response(io.BytesIO):
    def __init__(self, raw, status=206, content_range="bytes 3-5/30303207710"):
        super().__init__(raw)
        self.status = status
        self.headers = {"Content-Range": content_range}


class FetcherTests(unittest.TestCase):
    def test_ranges_reject_full_response_without_reading(self):
        response = Response(b"x" * 1000, status=200)
        response.read = mock.Mock(side_effect=AssertionError("must not read full response"))
        with self.assertRaisesRegex(ValueError, "HTTP 206"):
            fetch.RangeReader(lambda *a, **k: response).read(3, 3)
        response.read.assert_not_called()

    def test_ranges_enforce_headers_length_and_budget(self):
        for header, raw in (("bytes 0-2/30303207710", b"abc"),
                            ("bytes 3-5/30303207710", b"abcd")):
            with self.subTest(header=header, size=len(raw)), self.assertRaises(ValueError):
                fetch.RangeReader(lambda *a, **k: Response(raw, content_range=header)).read(3, 3)
        reader = fetch.RangeReader(mock.Mock())
        reader.total = fetch.MAX_TOTAL
        with self.assertRaisesRegex(ValueError, "budget"):
            reader.read(0, 1)
        reader.opener.assert_not_called()

    def test_timeout_retry_is_bounded_and_reserves_attempted_bytes(self):
        opener = mock.Mock(side_effect=[socket.timeout("synthetic timeout"), Response(b"abc")])
        reader = fetch.RangeReader(opener)
        with contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(reader.read(3, 3), b"abc")
        self.assertEqual(opener.call_count, 2)
        self.assertEqual(reader.total, 6)
        opener = mock.Mock(side_effect=socket.timeout("synthetic timeout"))
        with contextlib.redirect_stderr(io.StringIO()), self.assertRaises(socket.timeout):
            fetch.RangeReader(opener).read(3, 3)
        self.assertEqual(opener.call_count, 2)

    def test_crc_and_local_path_validation(self):
        raw, name = b"synthetic frame", "train_images/1/2/1.dcm"
        header = struct.pack("<4s5H3L2H", b"PK\x03\x04", 20, 0, 0, 0, 0,
                             zlib.crc32(raw), len(raw), len(raw), len(name), 0)
        archive = header + name.encode() + raw
        reader = mock.Mock()
        reader.read.side_effect = lambda start, size: archive[start:start + size]
        item = {"name": name, "offset": 0, "size": len(raw), "compressed": len(raw),
                "crc": zlib.crc32(raw), "method": 0}
        self.assertEqual(fetch.read_member(reader, item), raw)
        item["crc"] += 1
        with self.assertRaisesRegex(ValueError, "CRC"):
            fetch.read_member(reader, item)
        for unsafe in ("../frame.dcm", "/frame.dcm", "a//frame.dcm", "a\\frame.dcm"):
            with self.subTest(path=unsafe), self.assertRaises(ValueError):
                fetch.safe_path(unsafe)

    def test_archive_index_and_zip64_more_than_65535_entries(self):
        count = 65536
        records = []
        for number in range(count):
            name = "empty/{}/".format(number).encode()
            records.append(struct.pack("<4s6H3L5H2L", b"PK\x01\x02", 45, 45, 0, 0, 0, 0,
                                       0, 0, 0, len(name), 0, 0, 0, 0, 0, 0) + name)
        directory = b"".join(records)
        offset = 100
        position = offset + len(directory)
        zip64 = struct.pack("<4sQ2H2L4Q", b"PK\x06\x06", 44, 45, 45, 0, 0,
                            count, count, len(directory), offset)
        locator = struct.pack("<4sLQL", b"PK\x06\x07", 0, position, 1)
        end = struct.pack("<4s4H2LH", b"PK\x05\x06", 0, 0, 65535, 65535,
                          0xFFFFFFFF, 0xFFFFFFFF, 0)
        archive = b"x" * offset + directory + zip64 + locator + end
        reader = mock.Mock()
        reader.read.side_effect = lambda start, size: archive[start:start + size]
        with mock.patch.object(fetch, "ARCHIVE_SIZE", len(archive)):
            self.assertEqual(len(fetch.archive_index(reader)), count)

    def make_study(self, root):
        rows, files, csv_files = [], [], []
        for number, description in enumerate(fetch.DESCRIPTIONS, 1):
            rows.append({"study_id": "1", "series_id": str(number), "series_description": description})
            name = "train_images/1/{}/1.dcm".format(number)
            raw = "synthetic-{}".format(number).encode()
            path = root / name
            path.parent.mkdir(parents=True)
            path.write_bytes(raw)
            files.append({"relative_path": name, "size_bytes": len(raw),
                          "sha256": hashlib.sha256(raw).hexdigest(), "zip_crc_verified": True})
        tables = (rows, [{"study_id": "1", "series_id": "1", "condition": "Synthetic", "level": "L1/L2"}],
                  [{"study_id": "1", "synthetic_label": "unknown"}])
        for name, table in zip(fetch.CSVS, tables):
            raw = fetch.subset_csv(table, list(table[0]))
            (root / name).write_bytes(raw)
            csv_files.append({"relative_path": name, "size_bytes": len(raw),
                              "sha256": hashlib.sha256(raw).hexdigest(), "zip_crc_verified": True})
        provenance = {"repo_id": fetch.REPO, "revision": fetch.REVISION,
                      "archive_sha256": fetch.ARCHIVE_SHA256, "whole_archive_sha256_verified": False,
                      "study_id": "1", "files": files, "csv_files": csv_files,
                      "series": [{k: r[k] for k in ("series_id", "series_description")} for r in rows]}
        (root / "provenance.json").write_text(json.dumps(provenance))
        return provenance

    def test_nearby_members_use_one_bounded_network_block_and_keep_crc_checks(self):
        archive = bytearray()
        entries, expected = [], []
        for number in range(3):
            name = "train_images/1/2/{}.dcm".format(number)
            raw = "synthetic-frame-{}".format(number).encode()
            offset = len(archive)
            archive.extend(struct.pack("<4s5H3L2H", b"PK\x03\x04", 20, 0, 0, 0, 0,
                                       zlib.crc32(raw), len(raw), len(raw), len(name), 0))
            archive.extend(name.encode() + raw)
            entries.append({"name": name, "offset": offset, "size": len(raw),
                            "compressed": len(raw), "crc": zlib.crc32(raw), "method": 0})
            expected.append(raw)
        reader = mock.Mock()
        reader.read.side_effect = lambda start, size: bytes(archive[start:start + size])
        with mock.patch.object(fetch, "ARCHIVE_SIZE", len(archive)), contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual([raw for _, raw in fetch.grouped_members(reader, entries)], expected)
            reader.read.assert_called_once_with(0, len(archive))
            entries[-1]["crc"] += 1
            with self.assertRaisesRegex(ValueError, "CRC"):
                list(fetch.grouped_members(reader, entries))
        with self.assertRaisesRegex(ValueError, "exceeds"):
            fetch.BufferedRange(10, b"abc").read(9, 1)
        with self.assertRaisesRegex(ValueError, "exceeds"):
            fetch.BufferedRange(10, b"abc").read(12, 2)
        oversized = {"offset": 0, "compressed": fetch.MAX_INDEX}
        with self.assertRaisesRegex(ValueError, "block limit"):
            list(fetch.grouped_members(reader, [oversized]))

    def test_verify_only_never_uses_network_and_checks_hashes(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            provenance = self.make_study(root)
            with mock.patch.object(fetch.urllib.request, "urlopen") as opener, contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(fetch.main(["--output", str(root), "--verify-only"]), 0)
                opener.assert_not_called()
            (root / provenance["files"][0]["relative_path"]).write_bytes(b"corrupted")
            self.assertIsNone(fetch.verify_existing(root))
            with mock.patch.object(fetch, "download") as downloader, contextlib.redirect_stderr(io.StringIO()):
                self.assertEqual(fetch.main(["--output", str(root), "--verify-only"]), 2)
                downloader.assert_not_called()

    def test_provenance_duplicate_paths_and_traversal_are_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            provenance = self.make_study(root)
            self.assertIsNotNone(fetch.verify_existing(root))
            for bad in (provenance["files"][0]["relative_path"], "../external.dcm"):
                provenance["files"][1]["relative_path"] = bad
                (root / "provenance.json").write_text(json.dumps(provenance))
                self.assertIsNone(fetch.verify_existing(root))

    def test_deterministic_selection_requires_three_series_and_prefers_coverage(self):
        entries, series, coordinates = {}, [], []
        for study in ("1", "2", "3"):
            for number, description in enumerate(fetch.DESCRIPTIONS, 1):
                if study == "3" and number == 3:
                    continue
                series.append({"study_id": study, "series_id": str(number), "series_description": description})
                name = "train_images/{}/{}/1.dcm".format(study, number)
                entries[name] = {"name": name, "size": 10, "compressed": 8}
                for level in (("L1/L2", "L2/L3") if study == "2" else ("L1/L2",)):
                    coordinates.append({"study_id": study, "series_id": str(number),
                                        "condition": description, "level": level})
        self.assertEqual(fetch.choose_study(entries, series, coordinates)[0], "2")
        self.assertEqual(fetch.choose_study(entries, series, coordinates, "1")[0], "1")
        with self.assertRaisesRegex(ValueError, "three"):
            fetch.choose_study(entries, series, coordinates, "3")

    def test_output_inside_git_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / ".git").touch()
            with self.assertRaisesRegex(ValueError, "outside"):
                fetch.outside_git(root / "data")


if __name__ == "__main__":
    unittest.main()
